/**
 * @name Zip slip vulnerability in zipfile extraction
 * @description Extracting zip files without path validation can lead to directory traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Find zipfile extraction methods
    exists(API::CallNode call |
      (
        // zipfile.ZipFile.extract(member, ...)
        call = API::moduleImport("zipfile").getMember("ZipFile").getMember("extract").getACall() and
        sink = call.getArg(0)
      ) or (
        // zipfile.ZipFile.extractall(members, ...) - second parameter
        call = API::moduleImport("zipfile").getMember("ZipFile").getMember("extractall").getACall() and
        sink = call.getArg(1)
      ) or (
        // zipfile.extract(member, ...) - from zipfile module directly
        call = API::moduleImport("zipfile").getMember("extract").getACall() and
        sink = call.getArg(0)
      ) or (
        // zipfile.extractall(members, ...) - second parameter
        call = API::moduleImport("zipfile").getMember("extractall").getACall() and
        sink = call.getArg(1)
      )
    )
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Zip slip vulnerability from $@.", source.getNode(), "user input"

/**
 * @name Path traversal in wheel unpack operations
 * @description Untrusted input reaching wheel unpack operations can lead to path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module WheelUnpackConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for wheel unpack operations
    exists(API::CallNode call |
      // Check for zipfile.ZipFile constructor with file parameter
      call = API::moduleImport("zipfile").getMember("ZipFile").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // Check for open() calls with file paths
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // Check for os.path.join or similar path operations
      call = API::moduleImport("os").getMember("path").getMember("join").getACall() and
      sink = call.getArg(0)
    )
  }
}

module WheelUnpackFlow = TaintTracking::Global<WheelUnpackConfig>;
import WheelUnpackFlow::PathGraph

from WheelUnpackFlow::PathNode source, WheelUnpackFlow::PathNode sink
where WheelUnpackFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"

/**
 * @name Unsafe path concatenation leading to path traversal
 * @description Using os.path.join with untrusted input can lead to path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Find os.path.join calls where untrusted input could bypass security
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember("path").getMember("join").getACall()
      and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"
